use std::fs;
use std::path::{Path, PathBuf};

#[derive(Clone, Debug)]
pub struct Sheet {
    pub raw: String,
    pub rank: u8,
}

pub fn fold(s: &str) -> String {
    s.trim().to_ascii_lowercase().replace('-', "_")
}

pub fn desc_dir() -> PathBuf {
    PathBuf::from("/app/sanitdesc")
}

pub fn load_glob() -> Result<Vec<Sheet>, String> {
    let mut paths: Vec<PathBuf> = fs::read_dir(desc_dir())
        .map_err(|e| format!("cannot read sanitdesc: {e}"))?
        .filter_map(|e| e.ok())
        .map(|e| e.path())
        .filter(|p| p.extension().and_then(|s| s.to_str()) == Some("kind"))
        .collect();
    paths.sort();
    paths.iter().map(|p| parse_sheet(p)).collect()
}

fn parse_sheet(p: &Path) -> Result<Sheet, String> {
    let text = fs::read_to_string(p).map_err(|e| format!("{}: {e}", p.display()))?;
    let mut raw: Option<String> = None;
    let mut rank: Option<u8> = None;
    for line in text.lines().map(str::trim) {
        if let Some(rest) = line.strip_prefix("KIND") {
            let value = rest.trim();
            if value.is_empty() || raw.is_some() {
                return Err(format!("{}: invalid KIND", p.display()));
            }
            raw = Some(value.to_string());
        } else if let Some(rest) = line.strip_prefix("RANK") {
            if rank.is_some() {
                return Err(format!("{}: duplicate RANK", p.display()));
            }
            let value: u8 = rest.trim().parse()
                .map_err(|_| format!("{}: invalid RANK", p.display()))?;
            if value > 9 {
                return Err(format!("{}: RANK must be 0..9", p.display()));
            }
            rank = Some(value);
        }
    }
    let raw = raw.ok_or_else(|| format!("{}: missing KIND", p.display()))?;
    if fold(&raw).is_empty() {
        return Err(format!("{}: empty canonical KIND", p.display()));
    }
    let rank = rank.ok_or_else(|| format!("{}: missing RANK", p.display()))?;
    Ok(Sheet { raw, rank })
}

pub fn put_rec(buf: &mut Vec<u8>, name: &str, rank: u8) -> Result<(), String> {
    let bytes = name.as_bytes();
    let len = u16::try_from(bytes.len()).map_err(|_| format!("KIND too long: {name}"))?;
    buf.extend_from_slice(&len.to_be_bytes());
    buf.extend_from_slice(bytes);
    buf.push(rank);
    Ok(())
}

pub fn parse_recs(bytes: &[u8]) -> Result<Vec<(String, u8)>, String> {
    let mut out = Vec::new();
    let mut i = 0usize;
    while i < bytes.len() {
        if i + 2 > bytes.len() { return Err("truncated record length".into()); }
        let len = u16::from_be_bytes([bytes[i], bytes[i + 1]]) as usize;
        i += 2;
        if i + len + 1 > bytes.len() { return Err("truncated record".into()); }
        let name = std::str::from_utf8(&bytes[i..i + len])
            .map_err(|_| "record name is not UTF-8")?.to_string();
        i += len;
        let rank = bytes[i];
        i += 1;
        out.push((name, rank));
    }
    Ok(out)
}
