use crate::sheet;
use std::collections::BTreeMap;
use std::fs;

pub fn table(sheets: &[sheet::Sheet]) -> Result<BTreeMap<String, u8>, String> {
    let mut table = BTreeMap::new();
    for item in sheets {
        let name = sheet::fold(&item.raw);
        if let Some(old) = table.insert(name.clone(), item.rank) {
            if old != item.rank {
                return Err(format!("conflicting RANKs for {name}: {old} and {}", item.rank));
            }
        }
    }
    Ok(table)
}

pub fn hearth(names: &[String], ranks: &BTreeMap<String, u8>) -> Result<(), String> {
    let mut bytes = Vec::new();
    for name in names {
        let rank = *ranks.get(name).ok_or_else(|| format!("missing RANK for {name}"))?;
        sheet::put_rec(&mut bytes, name, rank)?;
    }
    fs::create_dir_all("/app/rankbin").map_err(|e| e.to_string())?;
    fs::write("/app/rankbin/ranks.bin", bytes).map_err(|e| e.to_string())
}
