use crate::{bake, roster, sheet};
use std::fs;

pub fn mark() -> i32 {
    if let Err(e) = brew() {
        eprintln!("brew: {e}");
        return 1;
    }
    0
}

fn brew() -> Result<(), String> {
    // This operational sidecar is intentionally read, but is not pipeline data.
    fs::read_to_string("/app/endpin/KEEP_TAIL.txt")
        .map_err(|e| format!("cannot read KEEP_TAIL.txt: {e}"))?;
    let sheets = sheet::load_glob()?;
    let ranks = bake::table(&sheets)?;
    let names = roster::collect(&sheets);

    let mut filed = Vec::new();
    for name in &names {
        let severity = *ranks.get(name).ok_or_else(|| format!("missing RANK for {name}"))?;
        if severity > 9 { return Err(format!("invalid severity for {name}")); }
        sheet::put_rec(&mut filed, name, severity)?;
    }
    // Refuse success unless every filed value agrees with the corresponding sheet rank.
    for (name, severity) in sheet::parse_recs(&filed)? {
        if ranks.get(&sheet::fold(&name)).copied() != Some(severity) {
            return Err(format!("filed severity does not match sheet for {name}"));
        }
    }

    roster::spill(&names)?;
    bake::hearth(&names, &ranks)?;
    fs::create_dir_all("/app/docket").map_err(|e| e.to_string())?;
    fs::write("/app/docket/filed.bin", filed).map_err(|e| e.to_string())?;
    Ok(())
}

pub fn peek() -> i32 {
    let bytes = match fs::read("/app/docket/filed.bin") {
        Ok(v) => v,
        Err(e) => { eprintln!("peek: {e}"); return 1; }
    };
    let recs = match sheet::parse_recs(&bytes) {
        Ok(v) => v,
        Err(e) => { eprintln!("peek: {e}"); return 1; }
    };
    print!("{{\"findings\":[");
    for (i, (name, rank)) in recs.iter().enumerate() {
        if i != 0 { print!(","); }
        print!("{{\"token\":{},\"severity\":{}}}", json_string(name), rank);
    }
    println!("]}}");
    0
}

fn json_string(s: &str) -> String {
    let mut out = String::from("\"");
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if c < '\u{20}' => out.push_str(&format!("\\u{:04x}", c as u32)),
            c => out.push(c),
        }
    }
    out.push('"');
    out
}
